export type CanadianProvince = 'BC' | 'AB' | 'ON' | 'QC' | 'SK' | 'MB' | 'NS' | 'NB' | 'NL' | 'PE' | 'YT' | 'NT' | 'NU';
export type LenderChannel = 'Prime (A)' | 'Monoline' | 'Alternative (B)' | 'Credit Union' | 'Private / MIC' | 'Commercial / Land';
export type PropertyTypeScope = 'Residential' | 'Commercial' | 'Agricultural' | 'Land' | 'Construction';

export interface LenderRateProduct {
  id: string;
  productName: string;
  term: '1 Year' | '2 Year' | '3 Year' | '4 Year' | '5 Year' | '7 Year' | '10 Year' | string;
  termType: 'Fixed' | 'Variable' | 'HELOC' | string;
  program: 'Insured' | 'Insurable' | 'Uninsured' | 'Alternative B' | 'Private Equity' | 'Commercial' | string;
  rate: number;
  spread?: string;
  apr?: number;
  rateType?: 'Standard' | 'Limited' | 'Promo' | string;
  rateHoldDays: number;
  maxLTV: number;
  maxAmortization?: number;
  prepaymentPrivilege?: string;
  cashback?: string;
  cashbackPercent?: number;
  notes?: string;
}

export interface LenderGuidelineItem {
  id: number | string;
  policy: string;
  description: string;
  isAccepted?: number | null;
}

export interface LenderDetail {
  id: string;
  name: string;
  channel: LenderChannel;
  categoryRaw: string;
  minBeacon: number;
  maxLTV: number;
  benchmarkRate: string;
  lowestRate: number;
  productsCount: number;
  isFeatured?: boolean;
  provinces: CanadianProvince[];
  lendingAreaNotes?: string;
  rateHoldDefault?: number;
  transactionTypes: ('Purchase' | 'Refinance' | 'Transfer' | string)[];
  purposes: ('Owner-Occupied' | 'Rental / Investment' | 'Second Home' | string)[];
  rateTypes: ('Standard' | 'Limited' | 'Promo' | string)[];
  programs: ('Insured' | 'Insurable' | 'Uninsured' | 'Alternative B' | 'Private Equity' | 'Commercial' | string)[];
  turnaround?: string;
  propertyTypes: PropertyTypeScope[];
  bestFor?: string;
  specialFeatures: string[];
  underwritingNotes: string;
  fitRationale: string;
  website: string;
  bdm: string;
  lastUpdated: string;
  rates: LenderRateProduct[];
  guidelines?: LenderGuidelineItem[];
}

